#include <iostream>
using namespace std;
using Integer = unsigned long long;

Integer gcd(Integer first, Integer second) {
    while (second != 0) {
        Integer remainder = first % second;
        first = second;
        second = remainder;
    }
    return first;
}

Integer lcm(Integer first, Integer second) {
    if (first == 0 || second == 0) {
        return 0;
    }
    Integer divisor = gcd(first, second);
    return (first / divisor) * second;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    cin >> q;

    for (int query = 0; query < q; ++query) {
        Integer first, second;
        cin >> first >> second;
        cout << gcd(first, second) << ' '
             << lcm(first, second) << '\n';
    }
    return 0;
}

